begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
insert into app.entitlements(school_id,code,enabled,effective_from) select s.id,c.code,true,'2026-09-01T00:00:00Z' from app.schools s cross join(values('learning'),('assessment'))c(code) on conflict(school_id,code) do update set enabled=true;
select ok(to_regclass('app.courses') is not null,'learning courses persist');
select ok(to_regclass('app.submissions') is not null,'immutable submitted revisions persist');
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app' and c.relname in ('courses','units','lessons','activities','activity_completions','assessments','submissions') and (not c.relrowsecurity or not c.relforcerowsecurity)),'learning records FORCE RLS');
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description) values('10000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Synthetic learning','School authored')$$,'assigned teacher creates course');
select lives_ok($$insert into app.courses(school_id,class_id,subject_id,created_by,title,description) values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Returned learning','School authored') returning id$$,'course insert returning observes new row through policy');
select throws_ok($$insert into app.courses(school_id,class_id,subject_id,created_by,title,description) values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000002','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Other class','')$$,'42501',null,'teacher cannot create in unassigned class');
insert into app.units(school_id,id,course_id,title,sequence) values('10000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','Unit',1);
insert into app.lessons(school_id,id,unit_id,title,sequence,body) values('10000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','Lesson',1,'School authored explanation');
insert into app.activities(school_id,id,lesson_id,title,kind,instructions,sequence) values('10000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','52000000-0000-4000-8000-000000000001','Practice','practice','Practice school objective',1);
insert into app.assessments(school_id,id,course_id,title,instructions,max_score,created_by) values('10000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000001','Assessment','Write',10,'20000000-0000-4000-8000-000000000004');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),0::bigint,'student cannot read draft course');
select throws_ok($$insert into app.activity_completions(school_id,activity_id,learner_id) values('10000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012')$$,'42501',null,'draft course cannot be completed');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update app.courses set status='PUBLISHED' where id='50000000-0000-4000-8000-000000000001';
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),1::bigint,'enrolled student sees published course');
select lives_ok($$insert into app.activity_completions(school_id,activity_id,learner_id) values('10000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012')$$,'student records own completion');
select lives_ok($$insert into app.submissions(school_id,assessment_id,learner_id,content) values('10000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Synthetic work')$$,'student submits own work');
select throws_ok($$insert into app.submissions(school_id,assessment_id,learner_id,content) values('10000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000013','Peer work')$$,'42501',null,'student cannot forge peer submission');
select throws_ok($$update app.submissions set content='changed'$$,'42501',null,'submitted revision immutable to runtime');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*) from app.submissions where assessment_id='54000000-0000-4000-8000-000000000001'),0::bigint,'parent cannot read unpublished submissions');
select throws_ok($$insert into app.submissions(school_id,assessment_id,learner_id,content) values('10000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000012','Parent work')$$,'42501',null,'parent cannot submit child work');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000013',true);
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),0::bigint,'unrelated class student denied course');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select is((select count(*) from app.submissions where assessment_id='54000000-0000-4000-8000-000000000001'),1::bigint,'course teacher sees submitted queue');
select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);
select is("authorization".unit_course('10000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001'),null::uuid,'private unit helper cannot enumerate another context');
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
reset role;
update app.classes set status='archived' where school_id='10000000-0000-4000-8000-000000000001' and id='30000000-0000-4000-8000-000000000001';
set local role cuevo_api;
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),0::bigint,'archived class cannot retain course access');
reset role;
update app.classes set status='active' where school_id='10000000-0000-4000-8000-000000000001' and id='30000000-0000-4000-8000-000000000001';
set local role cuevo_api;
reset role;
update app.teacher_assignments set status='revoked' where teacher_actor_id='20000000-0000-4000-8000-000000000004';
set local role cuevo_api;
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),0::bigint,'revoked assignment loses course access');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
reset role;
update app.enrollments set status='revoked' where school_id='10000000-0000-4000-8000-000000000001' and student_actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select is((select count(*) from app.courses where id='50000000-0000-4000-8000-000000000001'),0::bigint,'revoked enrollment loses learning access');
select is((select count(*) from app.submissions where assessment_id='54000000-0000-4000-8000-000000000001'),0::bigint,'revoked enrollment loses submitted content');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select set_config('app.school_id','10000000-0000-4000-8000-000000000002',true);
select is((select count(*) from app.courses),0::bigint,'cross school course denied');
reset role;
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles r on r.rolname in('anon','authenticated','service_role') where n.nspname='app' and c.relname in('courses','units','lessons','activities','activity_completions','assessments','submissions') and has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE')),'learning tables remain private from Data API');
select throws_ok($$update app.submissions set content='Owner change' where assessment_id='54000000-0000-4000-8000-000000000001'$$,'55000',null,'submitted revision immutable even for owner');
select throws_ok($$delete from app.activity_completions where activity_id='53000000-0000-4000-8000-000000000001'$$,'55000',null,'completion immutable even for owner');
select * from finish();
rollback;
